require_relative 'selection'

class KernelFit
  KAPPA = { 'epanechnikov' => 0.75, 'biweight' => 0.9375, 'triweight' => 1.09375 }.freeze
  attr_reader :fitted, :leverage, :edf

  def initialize(positions, values, bandwidth, kernel, local_linear, diagnostics: true)
    @positions, @y = positions, values
    @x = positions.map { |position| position / 100.0 }
    @bandwidth, @kernel, @local_linear = bandwidth, kernel, local_linear
    @cache = {}
    @fitted = @leverage = @edf = nil
    return unless diagnostics

    pairs = positions.map { |position| evaluate(position) }
    return if pairs.any? { |value, _weights| value.nil? }

    @fitted = pairs.map(&:first)
    @leverage = pairs.each_with_index.map { |(_value, weights), i| weights[i] }
    @edf = Selection.sum(@leverage)
  end

  def evaluate(position)
    return @cache[position] if @cache.key?(position)

    used = @positions.each_index.select { |i| (@positions[i] - position).abs < @bandwidth }
    return @cache[position] = [nil, nil] if used.length < (@local_linear ? 2 : 1)

    x0 = position / 100.0
    h = @bandwidth / 100.0
    differences = used.map { |i| @x[i] - x0 }
    kernels = differences.map do |delta|
      u = delta / h
      t = 1 - u * u
      weight = KAPPA.fetch(@kernel) * t
      weight *= t unless @kernel == 'epanechnikov'
      weight *= t if @kernel == 'triweight'
      weight
    end
    indices = used.each_index
    s0 = Selection.sum(kernels)
    t0 = Selection.sum(indices) { |j| kernels[j] * @y[used[j]] }
    weights = Array.new(@positions.length, 0.0)
    if @local_linear
      s1 = Selection.sum(indices) { |j| kernels[j] * differences[j] }
      s2 = Selection.sum(indices) { |j| kernels[j] * differences[j] * differences[j] }
      t1 = Selection.sum(indices) { |j| kernels[j] * differences[j] * @y[used[j]] }
      q = s0 * s2 - s1 * s1
      estimate = (s2 * t0 - s1 * t1) / q
      used.each_with_index { |i, j| weights[i] = kernels[j] * (s2 - s1 * differences[j]) / q }
    else
      estimate = t0 / s0
      used.each_with_index { |i, j| weights[i] = kernels[j] / s0 }
    end
    @cache[position] = [estimate, weights]
  end

  def estimate(position)
    evaluate(position).first
  end

  def weights(position)
    evaluate(position).last
  end
end

require_relative 'selection'

class LoessFit
  attr_reader :fitted, :leverage, :edf, :rho, :records

  def self.median(values)
    ordered = values.sort
    middle = ordered.length / 2
    ordered.length.odd? ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2.0
  end

  def self.cholesky(matrix)
    size = matrix.length
    lower = Array.new(size) { Array.new(size, 0.0) }
    size.times do |row|
      (0..row).each do |column|
        sigma = matrix[row][column]
        column.times { |k| sigma -= lower[row][k] * lower[column][k] }
        lower[row][column] = row == column ? Math.sqrt(sigma) : sigma / lower[column][column]
      end
    end
    lower
  end

  def self.solve(lower, right)
    size = right.length
    intermediate = Array.new(size, 0.0)
    size.times do |row|
      value = right[row]
      row.times { |k| value -= lower[row][k] * intermediate[k] }
      intermediate[row] = value / lower[row][row]
    end
    solution = Array.new(size, 0.0)
    (size - 1).downto(0) do |row|
      value = intermediate[row]
      ((row + 1)...size).each { |k| value -= lower[k][row] * solution[k] }
      solution[row] = value / lower[row][row]
    end
    solution
  end

  def initialize(positions, values, span, degree, iterations, diagnostics: true)
    @positions, @y, @span, @degree = positions, values, span, degree
    @x = positions.map { |position| position / 100.0 }
    @rho = Array.new(positions.length, 1.0)
    @records, @cache = [], {}
    @fitted = @leverage = @edf = nil
    return unless diagnostics

    fits = positions.map { |position| local_fit(position) }
    1.upto(iterations) do |iteration|
      residuals = values.each_index.map { |i| values[i] - fits[i][0] }
      scale = self.class.median(residuals.map(&:abs))
      @rho = residuals.map do |residual|
        u = residual / (6 * scale)
        nu = 1 - u * u
        u.abs < 1 ? nu * nu : 0.0
      end
      updated = positions.map { |position| local_fit(position) }
      change = fits.each_index.map { |i| (updated[i][0] - fits[i][0]).abs }.max
      @records << [iteration, scale, @rho.count(0.0), change]
      fits = updated
    end
    @cache = positions.zip(fits).to_h
    @fitted = fits.map(&:first)
    @leverage = fits.each_index.map { |i| @rho[i] * fits[i][1] }
    @edf = Selection.sum(@leverage)
  end

  def local_fit(position)
    count = @positions.length
    q = @span * count / 100
    neighborhood = @positions.each_index.sort_by { |i| [(@positions[i] - position).abs, i] }.first(q)
    distance = neighborhood.map { |i| (@positions[i] - position).abs }.max
    size = @degree + 1
    matrix = Array.new(size) { Array.new(size, 0.0) }
    right = Array.new(size, 0.0)
    x0 = position / 100.0
    rows = neighborhood.sort.map do |i|
      a = (@positions[i] - position).abs.to_f / distance.to_f
      s = 1 - a * a * a
      weight = s * s * s * @rho[i]
      delta = @x[i] - x0
      basis = @degree == 1 ? [1.0, delta] : [1.0, delta, delta * delta]
      size.times do |row|
        right[row] += weight * basis[row] * @y[i]
        size.times { |column| matrix[row][column] += weight * basis[row] * basis[column] }
      end
      [i, weight, basis]
    end
    lower = self.class.cholesky(matrix)
    beta = self.class.solve(lower, right)
    zeta = self.class.solve(lower, [1.0] + Array.new(@degree, 0.0))
    weights = Array.new(count, 0.0)
    rows.each do |i, weight, basis|
      weights[i] = weight * Selection.sum(0...size) { |k| zeta[k] * basis[k] }
    end
    [beta[0], zeta[0], weights]
  end

  def evaluate(position)
    @cache[position] ||= local_fit(position)
  end

  def estimate(position)
    evaluate(position)[0]
  end

  def weights(position)
    evaluate(position)[2]
  end
end

require_relative 'selection'

class SplineFit
  attr_reader :fitted, :leverage, :edf

  def initialize(positions, values, penalty, diagnostics: true)
    @positions, @penalty = positions, penalty
    @x = positions.map { |position| position / 100.0 }
    @h = @x.each_cons(2).map { |left, right| right - left }
    decompose
    @fit = fit_values(values)
    @fitted = @fit.first
    @basis = @leverage = @edf = nil
    prepare_basis if diagnostics
  end

  def decompose
    size = @positions.length - 2
    a = Array.new(size) { |i| 1.0 / @h[i] }
    c = Array.new(size) { |i| 1.0 / @h[i + 1] }
    b = Array.new(size) { |i| -(a[i] + c[i]) }
    diagonal = Array.new(size) do |i|
      (@h[i] + @h[i + 1]) / 3 + @penalty * (a[i] * a[i] + b[i] * b[i] + c[i] * c[i])
    end
    first = Array.new(size - 1) { |i| @h[i + 1] / 6 + @penalty * c[i] * (b[i] + b[i + 1]) }
    second = Array.new([size - 2, 0].max) { |i| @penalty * c[i] * c[i + 1] }
    @d, @l1, @l2 = Array.new(3) { Array.new(size, 0.0) }
    size.times do |i|
      @l2[i] = second[i - 2] / @d[i - 2] if i >= 2
      if i >= 1
        correction = i >= 2 ? @l2[i] * @d[i - 2] * @l1[i - 1] : 0.0
        @l1[i] = (first[i - 1] - correction) / @d[i - 1]
      end
      value = diagonal[i]
      value -= @l1[i] * @l1[i] * @d[i - 1] if i >= 1
      value -= @l2[i] * @l2[i] * @d[i - 2] if i >= 2
      @d[i] = value
    end
  end

  def fit_values(values)
    count = values.length
    size = count - 2
    z = Array.new(size, 0.0)
    size.times do |i|
      value = (values[i + 2] - values[i + 1]) / @h[i + 1] - (values[i + 1] - values[i]) / @h[i]
      value -= @l1[i] * z[i - 1] if i >= 1
      value -= @l2[i] * z[i - 2] if i >= 2
      z[i] = value
    end
    gamma = Array.new(count, 0.0)
    (size - 1).downto(0) do |i|
      value = z[i] / @d[i]
      value -= @l1[i + 1] * gamma[i + 2] if i + 1 < size
      value -= @l2[i + 2] * gamma[i + 3] if i + 2 < size
      gamma[i + 1] = value
    end
    omega = [(gamma[1] - gamma[0]) / @h[0]]
    (1...(count - 1)).each do |i|
      omega << (gamma[i + 1] - gamma[i]) / @h[i] - (gamma[i] - gamma[i - 1]) / @h[i - 1]
    end
    omega << (0 - (gamma[-1] - gamma[-2]) / @h[-1])
    fitted = values.each_index.map { |i| values[i] - @penalty * omega[i] }
    [fitted, gamma]
  end

  def evaluate_fit(fit, position)
    fitted, gamma = fit
    x0 = position / 100.0
    index = @positions.bsearch_index { |x| x >= position } || @positions.length
    return fitted[index] if index < @positions.length && @positions[index] == position

    if index.zero?
      slope = (fitted[1] - fitted[0]) / @h[0] - @h[0] * gamma[1] / 6
      return fitted[0] - (@x[0] - x0) * slope
    end
    if index == @positions.length
      slope = (fitted[-1] - fitted[-2]) / @h[-1] + @h[-1] * gamma[-2] / 6
      return fitted[-1] + (x0 - @x[-1]) * slope
    end
    i = index - 1
    left = x0 - @x[i]
    right = @x[i + 1] - x0
    (left * fitted[i + 1] + right * fitted[i]) / @h[i] -
      left * right * ((1 + left / @h[i]) * gamma[i + 1] + (1 + right / @h[i]) * gamma[i]) / 6
  end

  def prepare_basis
    return if @basis

    count = @positions.length
    @basis = Array.new(count) do |i|
      unit = Array.new(count, 0.0)
      unit[i] = 1.0
      fit_values(unit)
    end
    @leverage = @basis.each_index.map { |i| @basis[i][0][i] }
    @edf = Selection.sum(@leverage)
  end

  def estimate(position)
    evaluate_fit(@fit, position)
  end

  def weights(position)
    prepare_basis
    @basis.map { |fit| evaluate_fit(fit, position) }
  end
end
